        x=(np.array(a['xyz'])+AI@vec)%1
        h=atom('H'+a['label'][1:],'H',x,1.2*a['Uiso'],tolerance=.015)
        h['parent']=a['label'];h['parent_index']=i;hydrogens.append(h)
    return hydrogens

